import { test, expect } from '@playwright/test';

test.describe('Login Form Empty Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should prevent form submission when email and password fields are empty', async ({ page }) => {
    // Verify login form is visible
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Verify email input field exists and is empty
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toHaveValue('');

    // Verify password input field exists and is empty
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toHaveValue('');

    // Verify submit button is visible
    const submitButton = page.getByRole('button', { name: /sign in|login/i });
    await expect(submitButton).toBeVisible();

    // Attempt to submit the form with empty fields
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/email is required/i);
    await expect(errorMessage).toBeVisible();

    // Verify password error message appears
    const passwordError = page.getByText(/password is required/i);
    await expect(passwordError).toBeVisible();

    // Verify user remains on the login page
    await expect(page).toHaveURL(/\/login/);
  });

  test('should allow form submission when both email and password fields are filled', async ({ page }) => {
    // Fill email field with valid data
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    // Fill password field with valid data
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('ValidPassword123');

    // Verify error messages are not visible
    const errorMessage = page.getByText(/email is required/i);
    await expect(errorMessage).not.toBeVisible();

    const passwordError = page.getByText(/password is required/i);
    await expect(passwordError).not.toBeVisible();

    // Verify submit button is enabled
    const submitButton = page.getByRole('button', { name: /sign in|login/i });
    await expect(submitButton).toBeEnabled();

    // Submit the form
    await submitButton.click();

    // Verify successful login navigation
    await expect(page).toHaveURL(/\/dashboard/);
    await expect(page).toContainText('Welcome');
  });
});
